// ValidateCreateRequestBody runs the validations defined on CreateRequestBody
func ValidateCreateRequestBody(body *CreateRequestBody) (err error) {
	if body.Kind == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("kind", "body"))
	}
	if body.TenantURL == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("tenant_url", "body"))
	}
	if body.Kind != nil {
		if !(*body.Kind == "okta") {
			err = goa.MergeErrors(err, goa.InvalidEnumValueError("body.kind", *body.Kind, []any{"okta"}))
		}
	}
	return
}

